               .hps_0_hps_io_hps_io_uart0_inst_TX(HPS_UART_TX),             //                               .hps_io_uart0_inst_TX
               //HPS I2C1
               .hps_0_hps_io_hps_io_i2c0_inst_SDA(HPS_I2C0_SDAT),           //                               .hps_io_i2c0_inst_SDA
               .hps_0_hps_io_hps_io_i2c0_inst_SCL(HPS_I2C0_SCLK),           //                               .hps_io_i2c0_inst_SCL
               //HPS I2C2
               .hps_0_hps_io_hps_io_i2c1_inst_SDA(HPS_I2C1_SDAT),           //                               .hps_io_i2c1_inst_SDA
               .hps_0_hps_io_hps_io_i2c1_inst_SCL(HPS_I2C1_SCLK),           //                               .hps_io_i2c1_inst_SCL
               //GPIO
               .hps_0_hps_io_hps_io_gpio_inst_GPIO09(HPS_CONV_USB_N),       //                               .hps_io_gpio_inst_GPIO09
               .hps_0_hps_io_hps_io_gpio_inst_GPIO35(HPS_ENET_INT_N),       //                               .hps_io_gpio_inst_GPIO35
               .hps_0_hps_io_hps_io_gpio_inst_GPIO40(HPS_LTC_GPIO),         //                               .hps_io_gpio_inst_GPIO40
               .hps_0_hps_io_hps_io_gpio_inst_GPIO53(HPS_LED),              //                               .hps_io_gpio_inst_GPIO53
               .hps_0_hps_io_hps_io_gpio_inst_GPIO54(HPS_KEY),              //                               .hps_io_gpio_inst_GPIO54
               .hps_0_hps_io_hps_io_gpio_inst_GPIO61(HPS_GSENSOR_INT),      //                               .hps_io_gpio_inst_GPIO61
               //FPGA Partion
               .led_pio_external_connection_export(fpga_led_internal),      //    led_pio_external_connection.export
               .dipsw_pio_external_connection_export(SW),                   //  dipsw_pio_external_connection.export
               .button_pio_external_connection_export(fpga_debounced_buttons),
                                                                            // button_pio_external_connection.export
               //.hps_0_h2f_reset_reset_n(hps_fpga_reset_n),                  //                hps_0_h2f_reset.reset_n
               .hps_0_f2h_cold_reset_req_reset_n(~hps_cold_reset),          //       hps_0_f2h_cold_reset_req.reset_n
               .hps_0_f2h_debug_reset_req_reset_n(~hps_debug_reset),        //      hps_0_f2h_debug_reset_req.reset_n
               .hps_0_f2h_stm_hw_events_stm_hwevents(stm_hw_events),        //        hps_0_f2h_stm_hw_events.stm_hwevents
               .hps_0_f2h_warm_reset_req_reset_n(~hps_warm_reset),          //       hps_0_f2h_warm_reset_req.reset_n
									                      
					.myavalonbus32_0_conduit_end_addr       (avalon_addr),       //myavalonbus32_0_avalon_slave.address
					.myavalonbus32_0_conduit_end_read       (avalon_read),      // .read
					.myavalonbus32_0_conduit_end_write      (avalon_write),     // .write
					.myavalonbus32_0_conduit_end_readdata   (avalon_readdata),   // .readdata
					.myavalonbus32_0_conduit_end_writedata  (avalon_writedata), // .writedata
					.myavalonbus32_0_conduit_end_cs 			 (avalon_cs),        // .chipselect
					.myavalonbus32_0_conduit_end_bus_clk    ()           //  myavalonbus32_0_clk.clk
		
				
           );

//Avalon Bus interface 	
reg [15:0] control_reg;	
wire [15:0] status_net;
reg [15:0] ch_reg;	

wire [2:0] ch_select = ch_reg[2:0];
assign self_chk = control_reg[3];

assign status_net[15:0] = {8'b0,4'b0,self_chk,ch_select};
	
//{ch7,ch6,...ch0}, each channel use two bits for mux1,mux0

assign ch_gain[0] = `PCA_GAIN_BIT_L8[1:0];
assign ch_gain[1] = `PCA_GAIN_BIT_L8[3:2];
assign ch_gain[2] = `PCA_GAIN_BIT_L8[5:4];
assign ch_gain[3] = `PCA_GAIN_BIT_L8[7:6];
assign ch_gain[4] = `PCA_GAIN_BIT_H8[1:0];
assign ch_gain[5] = `PCA_GAIN_BIT_H8[3:2];
assign ch_gain[6] = `PCA_GAIN_BIT_H8[5:4];
assign ch_gain[7] = `PCA_GAIN_BIT_H8[7:6];

reg fifo_clr_reg; //needs to reset by itself after one SYS_CLK

wire avalon_write_i = avalon_write & avalon_cs;
wire avalon_read_i = avalon_read & avalon_cs;

reg avalon_write_o,avalon_read_o /*synthesis keep*/;
wire fifo_rd /*synthesis keep*/;
assign fifo_rd = (avalon_addr == FIFO_ADDR & (avalon_read_i == 1));

wire [SFIFO_WIDTH-1:0] slow_fifo_dout;
wire sfifo_rd /*synthesis keep*/;
assign sfifo_rd = (avalon_addr == SFIFO_ADDR & (avalon_read_i == 1)); 


assign rd_eeprom = (avalon_addr == EEPROM_RD_ADDR & (avalon_write_o == 1)); //load eeprom -> buffer
assign wr_eeprom = (avalon_addr == EEPROM_WR_ADDR & (avalon_write_o == 1));//write buffer -> eeprom

always @ (posedge SYS_CLK)
     avalon_write_o <= avalon_write_i;
	  
always @ (posedge SYS_CLK)
     avalon_read_o <= avalon_read_i;	  

////////////////////////////////////////////////////////////////////////////	  
//Registers and Configuration data write/read  
	  
always@(posedge SYS_CLK)
	if (~eeprom_busy && eeprom_data_valid) 
				configuration <= eeprom_buffer; 
	else begin
   /*   Write to Control Register   */
	if ((avalon_addr == CR_ADDR) & (avalon_write_o == 1) ) 
			control_reg <= avalon_writedata[15:0]; 	
	/*   Write to ch_select Register   */
	if ((avalon_addr == CH_SELECT_ADDR) & (avalon_write_o == 1) ) 
			ch_reg <= avalon_writedata[15:0]; 	
			
	/*   Read from Control Register   */		
	if ((avalon_addr == CR_ADDR) & (avalon_read_o == 1) ) 
			dout <= {16'b0,control_reg}; 
	
	/*   Read from Status Register   */		
	if ((avalon_addr == SR_ADDR) & (avalon_read_o == 1) ) 
			dout <= {16'b0,status_net};
			
   /*   Read FPGA version   */		
	if ((avalon_addr == FPGA_VER_ADDR) & (avalon_read_o == 1)) 
			dout <= FPGA_VERSION_NO; 

		
	
	/*   slow fifo occupancy     */		
	if ((avalon_addr == SFIFO_WD_ADDR) & (avalon_read_o == 1)) 
			dout <= {16'b0,8'b0,sfifo_rd_wd};
	

	/*   Read slow fifo     */		
	if ((avalon_addr == SFIFO_ADDR) & (avalon_read_o == 1)) 
			dout <= slow_fifo_dout; 	
	
	
	/*   Reset fast fifo     */		
	if ((avalon_addr == FIFO_CLR_ADDR) & (avalon_read_o == 1)) 
			fifo_clr_reg <= 1; 
	else fifo_clr_reg <= 0; 
  			
	/*   Read fast fifo occupancy    */		
	if ((avalon_addr == FIFO_WD_ADDR) & (avalon_read_o == 1)) 
			dout <= {16'b0,3'b0,fifo_word}; 
			
	/*   Read fast fifo   */		
	if ((avalon_addr == FIFO_ADDR) & (avalon_read_o == 1)) 
			dout <= {16'b0,fast_fifo_dout}; 	
	
   /*   Write to Mini-PCA Gain bits   */
	if ((avalon_addr == PCA_GAIN_ADDR) & (avalon_write_o == 1) ) 
			{`PCA_GAIN_BIT_H8,`PCA_GAIN_BIT_L8} <= avalon_writedata[15:0]; 
		
	/*   Read from Mini-PCA Gain Register   */
	if ((avalon_addr == PCA_GAIN_ADDR) & (avalon_read_o == 1) ) 
			dout <= {16'b0,`PCA_GAIN_BIT_H8,`PCA_GAIN_BIT_L8};  	

	/*   Write to Relay Register   */
	if ((avalon_addr == RELAY_ADDR) & (avalon_write_o == 1) ) 
			relay_reg <= avalon_writedata[7:0]; 
	
   /*   Write/Read to Ch0 Thresh  */
	if ((avalon_addr == CH0_TH_ADDR) & (avalon_write_o == 1) ) 
			`CH0_TH_BYTE <= avalon_writedata[7:0]; 
	if ((avalon_addr == CH0_TH_ADDR) & (avalon_read_o == 1) ) 
			dout <= {16'b0,8'b0,`CH0_TH_BYTE};  

   /*   Write/Read to Ch1 Thresh  */
	if ((avalon_addr == CH1_TH_ADDR) & (avalon_write_o == 1) ) 
			`CH1_TH_BYTE <= avalon_writedata[7:0]; 
	if ((avalon_addr == CH1_TH_ADDR) & (avalon_read_o == 1) ) 
			dout <= {16'b0,8'b0,`CH1_TH_BYTE};  
		
   /*   Write/Read to Ch2 Thresh  */
	if ((avalon_addr == CH2_TH_ADDR) & (avalon_write_o == 1) ) 
			`CH2_TH_BYTE <= avalon_writedata[7:0]; 
	if ((avalon_addr == CH2_TH_ADDR) & (avalon_read_o == 1) ) 
			dout <= {16'b0,8'b0,`CH2_TH_BYTE};  

   /*   Write/Read to Ch3 Thresh  */
	if ((avalon_addr == CH3_TH_ADDR) & (avalon_write_o == 1) ) 
			`CH3_TH_BYTE <= avalon_writedata[7:0]; 
	if ((avalon_addr == CH3_TH_ADDR) & (avalon_read_o == 1) ) 
			dout <= {16'b0,8'b0,`CH3_TH_BYTE};  
		
   /*   Write/Read to Ch4 Thresh  */
	if ((avalon_addr == CH4_TH_ADDR) & (avalon_write_o == 1) ) 
			`CH4_TH_BYTE <= avalon_writedata[7:0]; 
	if ((avalon_addr == CH4_TH_ADDR) & (avalon_read_o == 1) ) 
			dout <= {16'b0,8'b0,`CH4_TH_BYTE};  	
	
   /*   Write/Read to Ch5 Thresh  */
	if ((avalon_addr == CH5_TH_ADDR) & (avalon_write_o == 1) ) 
			`CH5_TH_BYTE <= avalon_writedata[7:0]; 
	if ((avalon_addr == CH5_TH_ADDR) & (avalon_read_o == 1) ) 
			dout <= {16'b0,8'b0,`CH5_TH_BYTE};  
		
   /*   Write/Read to Ch6 Thresh  */
	if ((avalon_addr == CH6_TH_ADDR) & (avalon_write_o == 1) ) 
			`CH6_TH_BYTE <= avalon_writedata[7:0]; 
	if ((avalon_addr == CH6_TH_ADDR) & (avalon_read_o == 1) ) 
			dout <= {16'b0,8'b0,`CH6_TH_BYTE};  
		
   /*   Write/Read to Ch7 Thresh  */
	if ((avalon_addr == CH7_TH_ADDR) & (avalon_write_o == 1) ) 
			`CH7_TH_BYTE <= avalon_writedata[7:0]; 
	if ((avalon_addr == CH7_TH_ADDR) & (avalon_read_o == 1) ) 
			dout <= {16'b0,8'b0,`CH7_TH_BYTE};  	
end
		
		
////////////////////////////////////////////////////////////
//Fast FIFO to transfer ADC rate data from FPGA to SoC
	
	wire fast_FIFO_rst = SYS_RST | fifo_clr_reg;
   wire fifo_wr /*synthesis keep*/;
	
	wire fast_fifo_full, fast_fifo_empty;
		
	wire [ADC_DATA_WIDTH-1:0] din;
   assign din	= (ch_select == 3'b000)? ADC_INTERFACE_DOUT[0]
					: (ch_select == 3'b001)? ADC_INTERFACE_DOUT[1]
					: (ch_select == 3'b010)? ADC_INTERFACE_DOUT[2]
					: (ch_select == 3'b011)? ADC_INTERFACE_DOUT[3]
					: (ch_select == 3'b100)? ADC_INTERFACE_DOUT[4]
					: (ch_select == 3'b101)? ADC_INTERFACE_DOUT[5]
					: (ch_select == 3'b110)? ADC_INTERFACE_DOUT[6]
					: (ch_select == 3'b111)? ADC_INTERFACE_DOUT[7]
					: 16'b0;
	
	wire [ADC_DATA_WIDTH-1:0] fast_fifo_dout;
	wire [12:0] fifo_word /*synthesis keep*/;
		
	fifo4096 Fast_FIFO (
		.aclr(fast_FIFO_rst), //
		.wrclk(ADC_CLK), //
		.rdclk(SYS_CLK), //
		.data(din), // input [15 : 0] din
		.wrreq(fifo_wr), //
		.rdreq(fifo_rd),
		.q(fast_fifo_dout), // output [15 : 0] dout
		.rdfull(fast_fifo_full), //
		.rdempty(fast_fifo_empty),
		.wrusedw(fifo_word) //
	);
	
	fifo_control fifo_control_inst(
		.RUN(1'b1),
		.rst(SYS_RST),
		.clk(ADC_CLK),

      .fifo_full(fast_fifo_full),
		.fifo_empty(fast_fifo_empty),
		.data_valid(ADC_data_valid), //input from ADC interface
		
		.wr(fifo_wr), // output, write Fast fifo
	
		.busy(busy) // output, not in use
	);
	
//================ processing ==============
	
wire processing_done = ADC_data_valid;

///================ Slow FIFO ===================

	reg sFIFO_wr;
	reg [SFIFO_WIDTH-1:0] sfifo_data_in;
	wire [7:0] sfifo_rd_wd,sfifo_wr_wd;
	wire sfifo_half_full = sfifo_wr_wd[6]; // 64   
	
	slfifo Slow_FIFO (
		.aclr(rst),
		.data(sfifo_data_in),
		.wrclk(ADC_CLK),
		.rdclk(SYS_CLK),
		.wrreq(sFIFO_wr),
		.rdreq(sfifo_rd),
		.q(slow_fifo_dout),
		.rdusedw(sfifo_rd_wd), 
		.wrusedw(sfifo_wr_wd)
	);  
//	output [7:0]  rdusedw;
//	output [7:0]  wrusedw;
// slfifo is 128 words(32bit) deep, Nov.29,2018
	
//============Packing=================================
	parameter PID = 32'h4142504d; // "ABPM"

	reg [7:0] p_state;

//data packet size is 16 words (32bit)
	always @(posedge ADC_CLK)
	begin
		if(rst)
			begin
				p_state <= 0;
				sFIFO_wr<= 0;
			end

		else
			begin
				case(p_state)
					0:if(processing_done && !sfifo_half_full) begin  sFIFO_wr<= 1; sfifo_data_in <= PID; p_state <= 1; end

					1: begin sfifo_data_in <= {16'b0,status_net}; p_state <= 2; end

					2: begin sfifo_data_in <= {16'b0,Ch_ADC_Reg[0]}; p_state <= 3; end
					3: begin sfifo_data_in <= {16'b0,Ch_ADC_Reg[1]}; p_state <= 4; end
					4: begin sfifo_data_in <= {16'b0,Ch_ADC_Reg[2]}; p_state <= 5; end
					5: begin sfifo_data_in <= {16'b0,Ch_ADC_Reg[3]}; p_state <= 6; end
					6: begin sfifo_data_in <= {16'b0,Ch_ADC_Reg[4]}; p_state <= 7; end
					7: begin sfifo_data_in <= {16'b0,Ch_ADC_Reg[5]}; p_state <= 8; end
					8: begin sfifo_data_in <= {16'b0,Ch_ADC_Reg[6]}; p_state <= 9; end
					9: begin sfifo_data_in <= {16'b0,Ch_ADC_Reg[7]}; p_state <= 10; end

					10: begin sfifo_data_in <= 0; p_state <= 11; end
					11: begin sfifo_data_in <= 0; p_state <= 12; end
					12: begin sfifo_data_in <= 0; p_state <= 13; end
					13: begin sfifo_data_in <= 0; p_state <= 14; end
					14: begin sfifo_data_in <= 0; p_state <= 15; end
					15: begin sfifo_data_in <= 0; p_state <= 16; end

					16: begin sFIFO_wr<= 0; p_state <= 0; end

					default:
					p_state <= 0;
				endcase
			end

	end

	
//============ self test pulse ============

clockdiv squrewave(
	.clk(SYS_CLK),
	.enable(self_chk),
   .oclk(test_pulse) 
);
  defparam squrewave.CLK_PERIOD = 20;      // ns, clk period default 50 MHz
  defparam squrewave.CLK_OUT_PERIOD = 100000000; //ns, outptu clock period, default 10 Hz
  defparam squrewave.CNT_WIDTH = 32;   // 
  
// Debounce logic to clean out glitches within 1ms		
debounce debounce_inst(
             .clk(fpga_clk_50),
             .reset_n(hps_fpga_reset_n),
             .data_in(KEY),
             .data_out(fpga_debounced_buttons)
         );
defparam debounce_inst.WIDTH = 2;
defparam debounce_inst.POLARITY = "LOW";
defparam debounce_inst.TIMEOUT = 50000;               // at 50Mhz this is a debounce time of 1ms
defparam debounce_inst.TIMEOUT_WIDTH = 16;            // ceil(log2(TIMEOUT))

// Source/Probe megawizard instance
hps_reset hps_reset_inst(
              .source_clk(fpga_clk_50),
              .source(hps_reset_req)
          );

altera_edge_detector pulse_cold_reset(
                         .clk(fpga_clk_50),
                         .rst_n(hps_fpga_reset_n),
                         .signal_in(hps_reset_req[0]),
                         .pulse_out(hps_cold_reset)
                     );
defparam pulse_cold_reset.PULSE_EXT = 6;
defparam pulse_cold_reset.EDGE_TYPE = 1;
defparam pulse_cold_reset.IGNORE_RST_WHILE_BUSY = 1;

altera_edge_detector pulse_warm_reset(
                         .clk(fpga_clk_50),
                         .rst_n(hps_fpga_reset_n),
                         .signal_in(hps_reset_req[1]),
                         .pulse_out(hps_warm_reset)
                     );
defparam pulse_warm_reset.PULSE_EXT = 2;
defparam pulse_warm_reset.EDGE_TYPE = 1;
defparam pulse_warm_reset.IGNORE_RST_WHILE_BUSY = 1;

altera_edge_detector pulse_debug_reset(
                         .clk(fpga_clk_50),
                         .rst_n(hps_fpga_reset_n),
                         .signal_in(hps_reset_req[2]),
                         .pulse_out(hps_debug_reset)
                     );
defparam pulse_debug_reset.PULSE_EXT = 32;
defparam pulse_debug_reset.EDGE_TYPE = 1;
defparam pulse_debug_reset.IGNORE_RST_WHILE_BUSY = 1;

reg [25: 0] counter;
reg led_level;
always @(posedge SYS_CLK or negedge hps_fpga_reset_n) begin
    if (~hps_fpga_reset_n) begin
        counter <= 0;
        led_level <= 0;
    end

    else if (counter == 20000000) begin
        led_level <= ~led_level;
    end

    else if (counter == 25000000) begin
        counter <= 0;
        led_level <= ~led_level;
    end
    
    else
        counter <= counter + 1'b1;
end

//assign LED[0] = led_level;
assign LED[0] = 0;
	
endmodule
